function countBits(n) {
  const ans = new Array(n + 1).fill(0)
  for (let i = 1; i <= n; i++) {
    ans[i] = ans[i >> 1] + (i & 1)
  }
  return ans
}

solution.python:
def count_bits(n):
    ans = [0] * (n + 1)
    for i in range(1, n + 1):
        ans[i] = ans[i >> 1] + (i & 1)   # i without its last bit, plus that bit
    return ans

